import { readFileSync } from "node:fs";
import { Agent } from "undici";   // npm i undici  (o fetch nativo nao envia certificado cliente)

const BASE = process.env.PIX_BASE_URL!;        // ex.: https://api.seupsp.com.br/pix/v2
const agente = new Agent({ connect: { cert: readFileSync(process.env.PIX_CERT_PEM!),
                                      key:  readFileSync(process.env.PIX_KEY_PEM!) } });

async function token(escopo: string): Promise<string> {
  const basic = Buffer.from(`${process.env.PIX_CLIENT_ID}:${process.env.PIX_CLIENT_SECRET}`).toString("base64");
  const r = await fetch(process.env.PIX_TOKEN_URL!, {
    method: "POST", dispatcher: agente,
    headers: { authorization: `Basic ${basic}`, "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "client_credentials", scope: escopo }),
  } as any);
  if (!r.ok) throw new Error(`token ${r.status}: ${await r.text()}`);
  return (await r.json() as any).access_token;
}

async function erro(r: Response): Promise<never> {
  const p: any = await r.json().catch(() => ({}));
  const viol = (p.violacoes ?? []).map((v: any) => `${v.propriedade}: ${v.razao}`).join("; ");
  throw new Error(`${r.status} ${p.type ?? ""} ${p.detail ?? ""} ${viol}`);
}

const txid = "pedido2026081200000000000042";
const corpo = {
  calendario: { expiracao: 3600 },
  devedor: { cnpj: "00000000000191", nome: "Comercio Exemplo Ltda" },
  valor: { original: "149.90" },
  chave: "00000000-0000-4000-8000-000000000000",
  solicitacaoPagador: "Pedido 4210",
};
const r = await fetch(`${BASE}/cob/${txid}`, {
  method: "PUT", dispatcher: agente,
  headers: { authorization: `Bearer ${await token("cob.write")}`, "content-type": "application/json" },
  body: JSON.stringify(corpo),
} as any);
if (r.status !== 201 && r.status !== 200) await erro(r);
const cob: any = await r.json();
console.log(cob.txid, cob.status, cob.pixCopiaECola);

