async function listarCobs(inicio: string, fim: string, status?: string) {
  const tk = await token("cob.read");
  const itens: any[] = [];
  for (let pagina = 0; ; pagina++) {
    const q = new URLSearchParams({ inicio, fim,
      "paginacao.paginaAtual": String(pagina), "paginacao.itensPorPagina": "1000" });
    if (status) q.set("status", status);
    const r = await fetch(`${BASE}/cob?${q}`, {
      dispatcher: agente, headers: { authorization: `Bearer ${tk}` } } as any);
    if (!r.ok) await erro(r);
    const d: any = await r.json();
    itens.push(...(d.cobs ?? []));
    if (pagina + 1 >= d.parametros.paginacao.quantidadeDePaginas) return itens;
  }
}
console.log((await listarCobs("2026-08-01T00:00:00Z", "2026-08-31T23:59:59Z", "CONCLUIDA")).length);

