import { readFileSync } from "node:fs";
import { Agent } from "undici";

const agente = new Agent({ connect: { cert: readFileSync(process.env.PIX_CERT_PEM!),
                                      key:  readFileSync(process.env.PIX_KEY_PEM!) } });
const cache = new Map<string, { tk: string; exp: number }>();

export async function token(escopo: string): Promise<string> {
  const agora = Date.now() / 1000;
  const c = cache.get(escopo);
  if (c && c.exp > agora + 30) return c.tk;
  const basic = Buffer.from(`${process.env.PIX_CLIENT_ID}:${process.env.PIX_CLIENT_SECRET}`).toString("base64");
  const r = await fetch(process.env.PIX_TOKEN_URL!, {
    method: "POST", dispatcher: agente,
    headers: { authorization: `Basic ${basic}`, "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "client_credentials", scope: escopo }),
  } as any);
  if (!r.ok) throw new Error(`token ${r.status}: ${await r.text()}`);
  const d: any = await r.json();
  cache.set(escopo, { tk: d.access_token, exp: agora + Number(d.expires_in ?? 300) });
  return d.access_token;
}

